// ── Build the Apify actor call from Whizz's search request ──
// NOTE: actorId and actorInput below are a best-effort guess at the 2GIS actor's real schema —
// see the Setup Notes sticky note. Adjust once you've confirmed the actor's actual Input tab.
const body = $('Webhook').first().json.body || {};
const query = (body.query || [body.brand, body.category].filter(Boolean).join(' ')).trim();
const location = (body.location || '').trim();
const limit = Math.max(1, Math.min(Number(body.limit) || 20, 50));

const ACTOR_ID = 'thenetaji~2gis-place-scraper';
const APIFY_TOKEN = 'YOUR_APIFY_TOKEN';

return [{
  json: {
    actorId: ACTOR_ID,
    apifyToken: APIFY_TOKEN,
    actorInput: {
      searchStringsArray: [query],
      locationQuery: location,
      maxCrawledPlaces: limit
    }
  }
}];

// ── Normalize the Apify dataset into what Whizz's Contact Discovery UI expects ──
// Defensive on field names for the same reason as Build Apify Request: unverified live.
const items = $input.all();
let rawItems = [];
let apiError = null;

for (const item of items) {
  const j = item.json;
  if (j && j.error) { apiError = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)); continue; }
  if (Array.isArray(j)) rawItems.push(...j);
  else if (j) rawItems.push(j);
}

if (apiError) {
  return [{ json: { contacts: [], error: `2GIS/Apify error: ${apiError}` } }];
}

const contacts = rawItems.map(it => ({
  name: it.title || it.name || it.storeName || it.company || '',
  phone: it.phone || it.phoneNumber || it.phoneUnformatted || (Array.isArray(it.phones) ? it.phones[0] : '') || '',
  email: it.email || (Array.isArray(it.emails) ? it.emails[0] : '') || '',
  website: it.website || it.domain || it.url_website || '',
  address: it.address || it.full_address || it.location || '',
  totalScore: it.totalScore || it.rating || it.stars || 0,
  url: it.url || it.link || it.placeUrl || it.googleMapsUrl || ''
})).filter(c => c.name);

return [{ json: { contacts } }];
